from hamana.connector.sql.sqlite import SQLiteConnector
from hamana.core.query import Query


def main() -> None:
    connector = SQLiteConnector(path="warehouse.db")
    query = Query(name="events_query", query="SELECT * FROM events")

    connector.connect()
    try:
        for batch in connector.query_batch(query, batch_size=5000):
            for row in batch:
                print(row)
    finally:
        connector.disconnect()


if __name__ == "__main__":
    main()
